const providerSetupScript=`const {app,db}=require('./server');const http=app.listen(0,'127.0.0.1',async()=>{try{const base='http://127.0.0.1:'+http.address().port+'/api/v1',login=await fetch(base+'/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone:'0200000099',pin:'654321'})});if(!login.ok)throw Error('seeded admin PIN login failed: '+await login.text());const{token}=await login.json(),headers={'Content-Type':'application/json',Authorization:'Bearer '+token},tenantResponse=await fetch(base+'/admin/tenants',{method:'POST',headers,body:JSON.stringify({name:'Provider Tenant'})}),{tenantId}=await tenantResponse.json();if(!tenantResponse.ok)throw Error('tenant setup failed');const configured=await fetch(base+'/admin/platform-settings',{method:'PUT',headers,body:JSON.stringify({tenantId,settings:{PAYMENT_PROVIDER:'eganow',EGANOW_BASE_URL:'https://developer.sandbox.egacoreapi.com',EGANOW_API_USERNAME:'setup-user',EGANOW_API_PASSWORD:'setup-password',EGANOW_X_AUTH:'setup-auth',SMS_PROVIDER:'twilio',TWILIO_API_BASE_URL:'https://api.twilio.com',TWILIO_SID:'test-sid',TWILIO_TOKEN:'test-token',TWILIO_FROM:'+123456'}})});if(!configured.ok)throw Error('admin provider setup failed: '+await configured.text());const result=await(await fetch(base+'/admin/platform-settings?tenantId='+tenantId,{headers})).json();if(!result.secrets.TWILIO_TOKEN||result.settings.PAYMENT_PROVIDER!='eganow')throw Error('provider setup was not persisted');if(JSON.stringify(result).includes('test-token'))throw Error('provider secret was returned');const invalidPayment=await fetch(base+'/admin/platform-settings',{method:'PUT',headers,body:JSON.stringify({tenantId,settings:{PAYMENT_PROVIDER:'mock'}})}),invalidSms=await fetch(base+'/admin/platform-settings',{method:'PUT',headers,body:JSON.stringify({tenantId,settings:{SMS_PROVIDER:'console'}})});if(invalidPayment.status!==400||invalidSms.status!==400)throw Error('non-production provider stubs were accepted');console.log('provider setup passed')}catch(error){console.error(error);process.exitCode=1}finally{http.close(()=>db.close())}})`;
const providerSetupEnv={...prodEnv,PAYMENT_PROVIDER:'',EGANOW_BASE_URL:'',EGANOW_API_USERNAME:'',EGANOW_API_PASSWORD:'',EGANOW_X_AUTH:'',SMS_PROVIDER:'',TWILIO_API_BASE_URL:'',TWILIO_SID:'',TWILIO_TOKEN:'',TWILIO_FROM:''};
const providerSetup=spawnSync(process.execPath,['-e',providerSetupScript],{cwd:__dirname,env:providerSetupEnv,encoding:'utf8'});
assert.equal(providerSetup.status,0,'production starts without provider credentials and the seeded admin can configure them: '+providerSetup.stderr);assert.ok(providerSetup.stdout.includes('provider setup passed'),'provider setup is confirmed');
const cashProdDB=path.join(TEST_ROOT,'production-cash.sqlite'),cashConfigDb=new D(cashProdDB);require('./migrate')(cashConfigDb);cashConfigDb.prepare("insert into config(scope,key,value) values('global','cash_enabled','1')").run();cashConfigDb.close();
const cashProd=spawnSync(process.execPath,['-e',"require('./server'); console.log('cash enabled')"],{cwd:__dirname,env:{...prodEnv,DB:cashProdDB,FEES_EGANOW_BASE_URL:'',FEES_EGANOW_API_USERNAME:'',FEES_EGANOW_API_PASSWORD:'',FEES_EGANOW_X_AUTH:''},encoding:'utf8'});
assert.equal(cashProd.status,0,'tenant-scoped app starts without global fee credentials: '+cashProd.stderr);assert.ok(cashProd.stdout.includes('cash enabled'),'cash routes no longer rely on global provider credentials');
